"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["90870"],{20576(e){e.exports=JSON.parse('{"id":"FIN-078","slug":"credit-history","term":"Credit History","also_known_as":[],"difficulty":"Beginner","definition":"Credit history is the record of how you have borrowed and repaid money over time. It shows lenders how reliably you have managed credit in the past.","explanation":["Your credit history includes when your accounts were opened, how much you have borrowed, whether you paid on time and whether any debts were defaulted on or sent to collections. It is recorded in your credit report and is a major input into your credit score.","Lenders value credit history because past behaviour is a useful guide to future behaviour. A long record of on-time payments across different kinds of credit suggests a reliable borrower.","People with no credit history, such as young adults or newcomers to a country, can find it hard to borrow, even if they have a good income. Lenders simply have no evidence either way. This is sometimes called having a thin credit file.","A credit history can be built gradually. Common steps include opening a basic credit card, using it for small purchases and paying the full balance every month, or taking a small credit-builder loan and repaying it on schedule. Over months and years, this creates a positive record that makes future borrowing easier and cheaper."],"note":"","total":1725,"prev":{"slug":"credit-freeze","term":"Credit Freeze"},"next":{"slug":"credit-inquiry","term":"Credit Inquiry"}}')}}]);